using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Threading;
using LSL;
using UnityEngine;
using UnityEngine.Events;

/// <summary>
/// Connects this application to the EEG_API_Unicorn engine with the settings of
/// StreamingAssets/eeg_api_config.json, starts the mode, and exposes its decisions. Drop it on any
/// GameObject. Do not edit this file: edit the configuration file, and react to the decisions
/// in your own scripts (onTargetChanged, DecisionReceived, or the properties below).
///
/// What happens, in order:
///   1. it creates its command stream and opens the engine's reply streams;
///   2. it waits to be connected: in the console, "Connect an application", pick this
///      application (its name starts with `app_name`), then "Connect";
///   3. for an SSVEP shown on a screen (`propose_refresh_hz`), it asks the engine for frequencies
///      that divide the refresh rate; then it sends the settings (set_params);
///   4. it starts the mode (start_mode); a mode with a model waits for the person to choose it
///      in the console ("Start decoding");
///   5. it reads the decisions of ITS engine, and raises onTargetChanged when the decoded target
///      changes (-1 = no decision, never target 0);
///   6. when the console disconnects it, or the engine stops, State becomes Disconnected;
///   7. when this component is disabled (Play stopped, scene changed, application closed), it
///      stops the mode it started and closes its streams.
///
/// For SSVEP, your scene renders the targets (one per entry of Frequencies, blinking at its
/// frequency, locked to the screen refresh), FROM THE START of the mode: the engine measures its
/// rest with the targets blinking, while the person looks at none of them.
///
/// ⚠️ Every Play creates a NEW command stream, so the console sees a new application: connect it
/// again after each Play. The LSL calls block: they run on a worker thread, never in Update().
/// </summary>
public class EegApiClient : MonoBehaviour
{
    /// <summary>The named subclass is what makes the event appear in the Inspector.</summary>
    [Serializable] public class TargetEvent : UnityEvent<int> { }

    public enum LinkState { Searching, WaitingToBeConnected, Setting, WaitingForTheMode, Decoding, Disconnected, Failed, Stopped }

    [Tooltip("The configuration file, in Assets/StreamingAssets/.")]
    public string configFile = "eeg_api_config.json";

    [Tooltip("Raised on the main thread when the decoded target (or MI task) changes, -1 included.")]
    public TargetEvent onTargetChanged = new TargetEvent();

    /// <summary>Raised on the main thread for every decision: the channels of the decoded stream, by name.</summary>
    public event Action<IReadOnlyDictionary<string, float>> DecisionReceived;

    /// <summary>Where the link stands. Read it to show the person what to do.</summary>
    public LinkState State => state;

    /// <summary>target_index (SSVEP, P300, c-VEP) or intent_index (MI) of the last decision; -1 = none.</summary>
    public int TargetIndex { get; private set; } = -1;

    /// <summary>The score of the last decision, on the scale of the stream's `decision_scale`.</summary>
    public float Confidence { get; private set; }

    /// <summary>The last decision, every channel by name (empty before the first one).</summary>
    public IReadOnlyDictionary<string, float> LastDecision => last;

    /// <summary>The number of decisions received, -1 included: are decisions flowing?</summary>
    public int DecisionCount { get; private set; }

    /// <summary>SSVEP: the frequencies to render, one per target, as proposed by the engine (else empty).</summary>
    public double[] Frequencies { get; private set; } = new double[0];

    /// <summary>The last message of the link, in plain English (also written to the Console).</summary>
    public string Message { get; private set; } = "";

    volatile LinkState state = LinkState.Searching;
    volatile bool stopping;
    Thread worker;
    EegApiConfig config;
    double screenHz;
    Dictionary<string, float> last = new Dictionary<string, float>();

    // The worker thread hands its results to the main thread through these queues.
    readonly ConcurrentQueue<Dictionary<string, float>> decisions = new ConcurrentQueue<Dictionary<string, float>>();
    readonly ConcurrentQueue<double[]> frequencies = new ConcurrentQueue<double[]>();
    readonly ConcurrentQueue<string> messages = new ConcurrentQueue<string>();

    void Start()
    {
        string path = Path.Combine(Application.streamingAssetsPath, configFile);
        try
        {
            config = EegApiConfig.Load(path);
        }
        catch (Exception e)
        {
            Fail("cannot read " + path + ": " + e.Message);
            return;
        }
        // Rounded: the engine expects the rate the targets are rendered at (60, not 59.94).
        screenHz = Math.Round(Screen.currentResolution.refreshRateRatio.value);
        worker = new Thread(Run) { IsBackground = true, Name = "EegApiClient" };
        worker.Start();
    }

    void Update()
    {
        while (messages.TryDequeue(out string message))
        {
            Message = message;
            Debug.Log("[EegApiClient] " + message);
        }
        while (frequencies.TryDequeue(out double[] set))
            Frequencies = set;
        while (decisions.TryDequeue(out Dictionary<string, float> decision))
        {
            last = decision;
            if (DecisionCount++ == 0)
                Debug.Log("[EegApiClient] first decision received from the engine");
            if (decision.TryGetValue("confidence", out float confidence))
                Confidence = confidence;
            int target = TargetIndex;
            if (decision.TryGetValue("target_index", out float t) || decision.TryGetValue("intent_index", out t))
                target = Mathf.RoundToInt(t);
            DecisionReceived?.Invoke(decision);
            if (target != TargetIndex)
            {
                TargetIndex = target;
                Debug.Log("[EegApiClient] decoded target: " + (target < 0 ? "none (-1)" : target.ToString()));
                onTargetChanged.Invoke(target);
            }
        }
    }

    void OnDisable()
    {
        if (worker == null)
            return;
        stopping = true;
        // The worker stops the mode it started (a reply takes at most a few seconds), then
        // closes its streams.
        worker.Join(8000);
        worker = null;
    }

    void Say(string message) => messages.Enqueue(message);

    void Fail(string why)
    {
        state = LinkState.Failed;
        Say("FAILED: " + why);
    }

    /// <summary>The whole session, on the worker thread.</summary>
    void Run()
    {
        EegApiLink link = null;
        bool startedHere = false;
        string mode = config.mode;
        try
        {
            // Steps 1 and 2: find the engine, then wait to be connected.
            link = new EegApiLink(config.app_name, Say);
            Say("Looking for an engine on the network, as '" + link.Name + "'");
            state = LinkState.WaitingToBeConnected;
            if (!link.Connect(config.search_timeout_s, () => stopping))
            {
                if (!stopping)
                    Fail("no engine on the network: is the console (or server.py) running?");
                return;
            }
            state = LinkState.Setting;
            // The engine is identified by its first reply: not yet known here.
            Say("Connected: the engine reads our commands");

            // Step 3: the settings. For an SSVEP on a screen, frequencies that divide its refresh
            // rate first (never write them in the code: they depend on the screen and the person).
            string settings = config.ParamsJson;
            double refresh = config.propose_refresh_hz < 0 ? screenHz : config.propose_refresh_hz;
            if (refresh > 0)
            {
                EngineReply proposed = link.Send("propose_params", mode, "{\"refresh_hz\": " + Json.Number(refresh) + "}");
                if (proposed == null || !proposed.accepted || proposed.value == null || proposed.value.Length == 0)
                {
                    Fail(Reason(link, proposed, "propose_params"));
                    return;
                }
                settings = Merge(settings, "\"refresh_hz\": " + Json.Number(refresh) +
                                           ", \"" + proposed.key + "\": " + Json.Numbers(proposed.value));
                frequencies.Enqueue(proposed.value);
            }
            if (!string.IsNullOrEmpty(settings) && settings != "{}")
            {
                EngineReply set = link.Send("set_params", mode, settings);
                if (set == null || !set.accepted)
                {
                    Fail(Reason(link, set, "set_params"));
                    return;
                }
            }

            // Step 4: start. SSVEP targets must blink from now on (see the summary above).
            EngineReply start = link.Send("start_mode", mode);
            if (start == null || !start.accepted)
            {
                Fail(Reason(link, start, "start_mode"));
                return;
            }
            // Stop only what WE started: a mode that was already running belongs to someone else.
            startedHere = !start.already_running;
            state = LinkState.WaitingForTheMode;
            if (start.deferred)
                Say("This mode needs a model: in the console, choose it, then click \"Start decoding\"");
            else
                Say("The mode warms up and measures its rest first: look at no target until the first decisions");

            // Step 5: the decisions of OUR engine, channels by name.
            StreamInlet decoded = link.OpenDecoded(mode, () => stopping, out string[] labels);
            var sample = new float[labels.Length];
            if (decoded != null)
                state = LinkState.Decoding;
            while (decoded != null && !stopping)
            {
                try
                {
                    if (decoded.pull_sample(sample, 0.2) != 0.0)
                    {
                        var decision = new Dictionary<string, float>(labels.Length);
                        for (int i = 0; i < labels.Length; i++)
                            decision[labels[i]] = sample[i];
                        decisions.Enqueue(decision);
                    }
                }
                catch (LostException)
                {
                    // The engine recreated the stream (new settings, new model): open it again.
                    decoded.Dispose();
                    decoded = link.OpenDecoded(mode, () => stopping, out labels);
                    sample = new float[labels.Length];
                    continue;
                }
                // Step 6: the console disconnected us, or the engine stopped.
                if (!link.Connected())
                    break;
            }
            decoded?.Dispose();
            if (!stopping && !link.Connected())
            {
                // The reason first: a script that sees Disconnected finds it in Message.
                Say(link.WhyDisconnected() + ". Play again to be connected again.");
                startedHere = false;    // the engine has already stopped what we started
                state = LinkState.Disconnected;
            }
        }
        catch (Exception e)
        {
            Fail(e.Message);
        }
        finally
        {
            // Step 7: stop what we started, then close our streams.
            if (link != null)
            {
                if (startedHere && config.stop_mode_on_exit && link.Connected())
                    link.Send("stop_mode", mode);
                link.Dispose();
            }
            if (stopping)
                state = LinkState.Stopped;
        }
    }

    /// <summary>Adds members to a JSON object written as text: {"a": 1} + "\"b\": 2" -> {"a": 1, "b": 2}.</summary>
    static string Merge(string jsonObject, string members)
    {
        string inner = string.IsNullOrEmpty(jsonObject) ? "" : jsonObject.Trim().TrimStart('{').TrimEnd('}').Trim();
        return "{" + (inner.Length > 0 ? inner + ", " : "") + members + "}";
    }

    /// <summary>Why a step failed: the engine's reason, a disconnection, or a lost reply.</summary>
    static string Reason(EegApiLink link, EngineReply reply, string step)
    {
        if (reply != null && !string.IsNullOrEmpty(reply.reason))
            return step + ": " + reply.reason;
        if (!link.Connected())
            return step + ": " + link.WhyDisconnected();
        return step + ": no reply (the command or its reply was lost)";
    }
}
